import assert from "node:assert/strict"
import test from "node:test"
import { existsSync, readFileSync } from "node:fs"
import { resolve } from "node:path"

const iosRoot = resolve(import.meta.dirname, "../ios")
const xcodeProjectPath = resolve(iosRoot, "Blumi.xcodeproj/project.pbxproj")
// `apps/mobile/ios` is generated by Expo prebuild and ignored by Git, so a
// clean clone or CI runner has no Xcode project to inspect. The check runs
// wherever the native project has been generated (the Mac development host).
const generatedIosProjectMissing = existsSync(xcodeProjectPath)
  ? false
  : "apps/mobile/ios is generated by Expo prebuild and not tracked in Git"

test("the Xcode target uses Expo's development bundle resolver and an embedded release bundle", { skip: generatedIosProjectMissing }, () => {
  const project = readFileSync(xcodeProjectPath, "utf8")
  const delegatePath = project.match(/path = (Blumi\/AppDelegate\.swift);/)?.[1]
  assert.ok(delegatePath, "the Xcode target must reference its AppDelegate source")
  const source = readFileSync(resolve(iosRoot, delegatePath), "utf8")

  assert.match(source, /bridge\.bundleURL \?\? bundleURL\(\)/)
  assert.match(
    source,
    /#if DEBUG\s+return RCTBundleURLProvider\.sharedSettings\(\)\.jsBundleURL\(forBundleRoot: "\.expo\/\.virtual-metro-entry"\)\s+#else\s+return Bundle\.main\.url\(forResource: "main", withExtension: "jsbundle"\)/
  )
  assert.doesNotMatch(source, /packagerHost:\s*"127\.0\.0\.1"/)
})
